<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\AdminUser; use App\Services\AuditService; use Illuminate\Http\{RedirectResponse,Request}; use Illuminate\Support\Facades\Auth;
class LoginController extends Controller { public function create(){return view('admin.auth.login',['pageConfigs'=>['myLayout'=>'blank']]);} public function store(Request $r,AuditService $audit): RedirectResponse { $d=$r->validate(['email'=>'required|email','password'=>'required|string','remember'=>'nullable|boolean']); $user=AdminUser::where('email',$d['email'])->first(); if(!$user||!$user->active||!Auth::attempt(['email'=>$d['email'],'password'=>$d['password'],'active'=>true],(bool)($d['remember']??false))){return back()->withErrors(['email'=>'Credenciales inválidas o usuario inactivo.'])->onlyInput('email');} $r->session()->regenerate(); $user->update(['last_login_at'=>now(),'last_login_ip'=>$r->ip()]); $audit->record('login','Inicio de sesión administrativo.',$user); return redirect()->intended(route('dashboard')); } public function destroy(Request $r,AuditService $audit): RedirectResponse {$audit->record('logout','Cierre de sesión administrativo.',auth()->user()); Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login');} }
